+            if (output) AudioNodeOutput::disconnectAll(gLock, output);
+        }
+        return;
+    }
     m_internal->pendingNodeConnections.enqueue({ConnectionOperationKind::Disconnect, node, std::shared_ptr<AudioNode>(), index, 0});
 }

